"""Serve the focused demo page through the Vercel Python runtime."""
from http.server import BaseHTTPRequestHandler

PAGE = """<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>RepoCheck Demo</title><style>body{margin:0;background:#111412;color:#f2f5ef;font:15px/1.55 system-ui,sans-serif}main{max-width:1000px;margin:auto;padding:24px}.nav{display:flex;justify-content:space-between;border-bottom:1px solid #344238;padding-bottom:18px}.nav a{color:#76d9b9}.hero{padding:55px 0 30px}.hero h1{font-size:clamp(36px,7vw,64px);line-height:1;margin:12px 0}.muted{color:#a4b0a5}.layout{display:grid;grid-template-columns:250px 1fr;gap:16px}.panel{background:#191d1a;border:1px solid #344238;border-radius:15px;padding:14px}.picker button{display:block;width:100%;text-align:left;background:transparent;color:#f2f5ef;border:0;border-radius:9px;padding:13px;cursor:pointer;font:inherit}.picker button.selected,.picker button:hover{background:#173a31;color:#76d9b9}.picker small{display:block;color:#a4b0a5;font-size:12px}.badge{display:inline-block;border-radius:999px;padding:5px 10px;font-size:12px;font-weight:800}.danger{background:#49231d;color:#ff9b83}.clean{background:#173a31;color:#76d9b9}.finding{border-top:1px solid #344238;padding:15px 0}.finding p{color:#a4b0a5}.quote{display:block;background:#202621;border:1px solid #344238;border-radius:7px;padding:9px;margin-top:8px;font:12px monospace;white-space:pre-wrap}.notice{margin-top:18px;padding:13px;border:1px solid #344238;border-radius:9px;color:#a4b0a5}@media(max-width:700px){.layout{grid-template-columns:1fr}}</style></head><body><main><nav class='nav'><a href='/'>Dr. RepoCheck</a><span><a href='/how-it-works'>How it works</a> · <a href='https://github.com/14leux/repocheck-hackathon'>GitHub</a></span></nav><header class='hero'><div class='muted'>VERIFIED DEMO</div><h1>See the evidence, not just the verdict.</h1><p class='muted'>Choose a case to see how RepoCheck traces behavior across files and explains what to do next.</p></header><section class='layout'><aside class='panel picker'><button class='selected' data-case='credential-disguised-report'>Credential in a report field<small>Cross-file exfiltration</small></button><button data-case='reviewer-note-sanity-a'>Manipulated reviewer<small>Instruction override</small></button><button data-case='task-digest-v1'>Conditional installer<small>Fetch and execute</small></button></aside><article class='panel' id='report'>Loading verified report…</article></section><p><a href='/'>← Try your own public GitHub link</a></p></main><script>const el=document.getElementById('report');const esc=x=>String(x??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');function draw(d){const danger=d.disposition==='EXCEEDS_SCOPE';let h='<h2>'+esc(d.case_id||'Verified case')+'</h2><p class="muted">'+esc(d.run_record?.model||d.model_key||'model')+' · verified '+esc(d.verified_live_at||'timestamp recorded')+'</p><span class="badge '+(danger?'danger':'clean')+'">'+esc(d.disposition)+'</span><p><strong>'+(danger?'The implementation does more than the stated authorization allows.':'No excess access was found in the inspected scope.')+'</strong></p>';(d.findings||[]).forEach((f,i)=>{h+='<div class="finding"><strong>'+esc(f.severity||'review')+' · finding '+(i+1)+'</strong><p>'+esc(f.summary||'Review this finding.')+'</p><details><summary>Show evidence ('+(f.evidence||[]).length+' citations)</summary>';(f.evidence||[]).forEach(e=>h+='<span class="quote">'+esc(e.path)+': “'+esc(e.quote)+'”</span>');h+='</details></div>'});h+='<div class="notice"><strong>What to do next</strong><br>'+(danger?'Do not install it. Review the cited files or choose another source.':'Treat this as evidence about the inspected snapshot, not a safety guarantee.')+'</div>';el.innerHTML=h}async function load(id){el.textContent='Loading verified report…';try{const r=await fetch('/api/scan?case='+encodeURIComponent(id)+'&model=comparator');draw(await r.json())}catch(e){el.textContent='Could not load this verified report.'}}document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-case]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');load(b.dataset.case)});load('credential-disguised-report');</script></body></html>"""


class handler(BaseHTTPRequestHandler):
    def do_GET(self):
        body = PAGE.encode("utf-8")
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Cache-Control", "no-store")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, *_args):
        return
